<script>
import api from '../api.js';
import ProjectWizard from './ProjectWizard.vue';
export default {
 name:'AdminPanel',components:{ProjectWizard},props:{project:String,target:String,kind:String,initialKey:String},emits:['changed','dirty'],
 data(){return {data:null,error:'',notice:'',busy:false,section:'',form:null,groupKey:'',group:null,xml:'',ruleIndex:-1,ruleProps:{},creatingGroup:false,groupName:''}},
 async mounted(){this.section=this.kind==='security'?'security':this.kind;if(this.kind!=='project-create')await this.load();if(this.kind==='security'&&this.initialKey){this.groupKey=this.initialKey;await this.loadGroup()}},
 methods:{
 args(){return {project:this.project,target:this.target}},
 systemLabel(key){return ({core_version:'Ядро TACTIC',ui_version:'Нативный интерфейс',python:'Python',platform:'Система',http_server:'HTTP-сервер',database_vendor:'Движок базы',project:'Текущий проект',projects:'Проектов',database_checked:'Запрос к базе выполнен',allow_writes:'Запись разрешена',allow_uploads:'Загрузка разрешена',admin_only:'Только администраторы'})[key]||key},
 async load(){this.error='';this.busy=true;try{const path=this.section==='security'?'/security':this.kind==='project-create'?'/project-create':this.kind==='system'?'/system':'/users';this.data=await api.request(path,this.args());this.form=null}catch(e){this.error=e.message}finally{this.busy=false}},
 async switchSection(section){this.section=section;this.group=null;this.groupKey='';await this.load()},
 edit(row=null){this.form={record:row,login:row?.values.login||'',values:Object.fromEntries((this.data?.edit_fields||[]).map(f=>[f.name,row?.values[f.name]??''])),password:''};delete this.form.values.login},
 async saveUser(){this.busy=true;this.error='';try{const f=this.form,args={...this.args(),key:f.record?.key,revision:f.record?.revision,login:f.login,values:f.values};if(f.password)args.password=f.password;await api.request('/users',args,f.record?'PATCH':'POST');this.form.password='';this.form=null;await this.load();this.notice='Пользователь сохранён исходной моделью Login'}catch(e){this.error=e.message}finally{this.busy=false}},
 async loadGroup(){this.busy=true;this.error='';try{this.group=await api.request('/security',{...this.args(),key:this.groupKey});this.xml=this.group.xml;this.ruleIndex=-1}catch(e){this.error=e.message}finally{this.busy=false}},
 async addGroup(){this.busy=true;this.error='';try{const r=await api.request('/security',{...this.args(),name:this.groupName},'POST');await this.load();this.groupKey=r.key;this.creatingGroup=false;await this.loadGroup()}catch(e){this.error=e.message}finally{this.busy=false}},
 rules(){try{const d=new DOMParser().parseFromString(this.xml,'application/xml');return Array.from(d.documentElement.children).filter(n=>n.tagName==='rule').map(n=>Object.fromEntries(Array.from(n.attributes).map(a=>[a.name,a.value])))}catch{return []}},
 selectRule(index){this.ruleIndex=index;this.ruleProps={...(this.rules()[index]||{})}},
 editRule(remove=false){this.error='';try{const doc=new DOMParser().parseFromString(this.xml,'application/xml');if(doc.querySelector('parsererror')||doc.documentElement.tagName!=='rules')throw Error('Некорректный XML правил');const rules=Array.from(doc.documentElement.children).filter(n=>n.tagName==='rule');let rule=rules[this.ruleIndex];if(remove){if(rule)rule.remove()}else{if(!rule){rule=doc.createElement('rule');doc.documentElement.appendChild(rule)}for(const key of ['group','project','element','search_type','key','code','access']){const value=this.ruleProps[key];if(value===undefined)continue;if(value==='')rule.removeAttribute(key);else rule.setAttribute(key,value)}}this.xml=new XMLSerializer().serializeToString(doc);this.ruleIndex=-1;this.ruleProps={}}catch(e){this.error=e.message}},
 async saveGroup(){this.busy=true;this.error='';try{const r=await api.request('/security',{...this.args(),key:this.groupKey,revision:this.group.revision,xml:this.xml},'PATCH');await this.loadGroup();this.notice=r.notice}catch(e){this.error=e.message}finally{this.busy=false}}
 }
};
</script>
<template>
<section class="admin-panel"><div v-if="kind==='users'" class="toolbar"><button :class="{primary:section==='users'}" @click="switchSection('users')">Пользователи</button><button :class="{primary:section==='security'}" @click="switchSection('security')">Правила групп</button></div><p v-if="error" class="error">{{error}}</p><p v-if="notice" class="notice">{{notice}}</p><p v-if="busy" class="muted">Запрос к TACTIC…</p>
<template v-if="section==='users'"><div class="toolbar"><button class="primary" :disabled="busy||!data?.can_write" @click="edit()">+ Пользователь</button><button @click="load">Перечитать</button><small>Поля списка из manage_user widget_config. Пароли не возвращаются API.</small></div><div class="table-scroll"><table><thead><tr><th v-for="f in data?.fields" :key="f.name">{{f.label}}</th><th></th></tr></thead><tbody><tr v-for="row in data?.items" :key="row.key"><td v-for="f in data.fields" :key="f.name">{{row.values[f.name]}}</td><td><button :disabled="!data.can_write" @click="edit(row)">Изменить</button></td></tr></tbody></table></div>
<div v-if="form" class="modal-backdrop"><section class="modal"><header><h2>{{form.record?'Изменить пользователя':'Новый пользователь'}}</h2><button @click="form=null">×</button></header><form @submit.prevent="saveUser"><div class="form-scroll"><label>Логин<input v-model="form.login" :disabled="!!form.record" required></label><label v-for="f in data.edit_fields" :key="f.name">{{f.label}}<input v-model="form.values[f.name]"></label><label>{{form.record?'Новый пароль (пусто — не менять)':'Начальный пароль'}}<input v-model="form.password" type="password" autocomplete="new-password" :required="!form.record" minlength="10"></label><small>Пароль передаётся штатному Login.set_password. Встроенный admin защищён.</small><p v-if="error" class="error">{{error}}</p></div><footer><button type="button" @click="form=null">Отмена</button><button class="primary" :disabled="busy">Сохранить</button></footer></form></section></div></template>
<template v-else-if="section==='security'"><div class="toolbar"><select v-model="groupKey" @change="loadGroup"><option value="">Группа…</option><option v-for="g in data?.items" :key="g.key" :value="g.key">{{g.name}}</option></select><button :disabled="!data?.can_write" @click="creatingGroup=!creatingGroup">+ Группа</button><span class="spacer"></span><button class="primary" :disabled="busy||!group?.can_write||xml===group?.xml" @click="saveGroup">Сохранить правила</button></div><form v-if="creatingGroup" class="toolbar" @submit.prevent="addGroup"><input v-model="groupName" placeholder="Имя группы" required><button :disabled="busy">Создать</button></form><p class="notice">Настоящие access_rules группы. Правки могут изменить доступ пользователей. Встроенная admin-группа защищена; вычислитель прав остаётся исходным.</p><div v-if="group" class="security-editor"><div><h3>{{group.name}}</h3><button :disabled="!group.can_write" @click="selectRule(-1)">Новое правило</button><table><thead><tr><th>Group</th><th>Element / Type</th><th>Access</th></tr></thead><tbody><tr v-for="(rule,i) in rules()" :key="i" @click="selectRule(i)" :class="{selected:ruleIndex===i}"><td>{{rule.group}}</td><td>{{rule.element||rule.search_type||rule.code||rule.key}}</td><td>{{rule.access}}</td></tr></tbody></table><form @submit.prevent="editRule()"><div class="two-cols"><label v-for="f in ['group','project','element','search_type','key','code','access']" :key="f">{{f}}<input v-model="ruleProps[f]"></label></div><button :disabled="!group.can_write">Применить правило</button><button type="button" :disabled="!group.can_write||ruleIndex<0" @click="editRule(true)">Удалить правило</button></form></div><label>XML access_rules<textarea v-model="xml" class="code-input" rows="28" :readonly="!group.can_write" spellcheck="false"></textarea></label></div></template>
<ProjectWizard v-else-if="kind==='project-create'" :project="project" :target="target" @dirty="$emit('dirty',$event)" @changed="$emit('changed',$event)"/>
<div v-else-if="kind==='system'" class="system-panel">
<div class="widget-toolbar" role="group" aria-label="Диагностика сервера"><button :disabled="busy" @click="load">Проверить снова</button></div>
<dl class="system-summary"><template v-for="(value,key) in data" :key="key"><div v-if="key!=='schema'&&key!=='notes'&&key!=='cluster'" class="system-fact"><dt>{{systemLabel(key)}}</dt><dd>{{typeof value==='boolean'?(value?'Да':'Нет'):value}}</dd></div></template></dl>
<section v-if="data?.cluster?.enabled" class="cluster-status" aria-label="Рабочие процессы TACTIC">
<header class="toolbar"><h3>Рабочие процессы</h3><span class="cluster-state">{{({running:"Работает",starting:"Запуск",degraded:"Частично доступно",failed:"Ошибка",stopped:"Остановлено"})[data.cluster.state]||data.cluster.state}}</span><span class="spacer"></span><small>Ответил процесс {{data.cluster.current_worker}}</small></header>
<p class="muted">Чтение распределяется между доступными процессами. Вход, изменения и legacy API обслуживает ведущий процесс. Запись после обрыва не повторяется автоматически.</p>
<div class="table-scroll"><table><thead><tr><th>Процесс</th><th>PID</th><th>Роль</th><th>Состояние</th><th>Запросы</th><th>Сейчас</th><th>Перезапуски</th></tr></thead><tbody><tr v-for="w in data.cluster.workers" :key="w.id"><td>{{w.id}}</td><td>{{w.pid}}</td><td>{{w.role==='writer'?'Ведущий / чтение и запись':'Чтение'}}</td><td><span class="cluster-health" :data-state="w.healthy?'up':'down'">{{w.healthy?'Доступен':'Недоступен'}}</span></td><td>{{w.requests}}</td><td>{{w.active}}</td><td>{{w.restarts}}</td></tr></tbody></table></div>
<small class="muted">Обновлено: {{data.cluster.updated_at}}. Это состояние процессов, не проверка целостности базы. Для offline-обновления необходимо остановить всю группу.</small>
</section>
<div class="system-notes"><p v-for="(note,i) in data?.notes" :key="i" class="muted">{{note}}</p></div>
<section v-if="data?.schema" class="schema-health" aria-label="Проверка схемы базы">
<header><h3>Структура базы TACTIC</h3><strong :class="data.schema.ready?'success':'error'">{{data.schema.ready?'Обязательная структура найдена':'Требуется проверка схемы'}}</strong></header>
<p class="muted">{{data.schema.notice}}</p><p class="notice">{{data.schema.upgrade_notice}}</p>
<p v-if="data.schema.error" class="error">{{data.schema.error}}</p>
<section v-for="db in data.schema.databases" :key="db.project" class="schema-database">
<div class="toolbar"><h4>{{db.project}}</h4><span class="pill">{{db.vendor||'Метаданные недоступны'}}</span><span class="spacer"></span><span>{{db.checked_tables||0}} таблиц проверено</span></div>
<p v-if="db.error" class="error">{{db.notice}}</p><div class="table-scroll"><table class="schema-check-table"><thead><tr><th>Исходная таблица / SearchType</th><th>Состояние</th><th>Отсутствующие поля</th></tr></thead><tbody><tr v-for="(check,i) in db.checks" :key="i" :data-schema-state="check.state"><td><code>{{check.table||check.search_type}}</code></td><td :class="check.state==='ok'?'muted':'error'">{{({ok:'Найдена',missing_columns:'Нет полей',missing_table:'Нет таблицы',missing_registration:'Нет регистрации'})[check.state]||check.state}}</td><td>{{check.missing_columns?.join(', ')||'—'}}</td></tr></tbody></table></div>
</section>
<p class="muted">Только чтение метаданных. Проверка не создаёт таблицы, не запускает миграции и не меняет widget_config.</p>
</section></div>
</section>
</template>
